                n1_list = phi_preimages(K, p)
                for n1 in n1_list:
                    fac_n1 = factor(n1)
                    ok = True
                    for q, a in fac_n1.items():
                        if (q ** a) > (p ** alpha):
                            ok = False
                            break
                    if not ok:
                        continue
                    b = (p ** alpha) * n1
                    # Verify equality for safety
                    # f(b) = phi(b)/2
                    phi_b = 1
                    for q, a in factor(b).items():
                        phi_b *= (q ** (a - 1)) * (q - 1)
                    f_b = phi_b // 2
                    # g(b^s)
                    max_val = -1
                    max_p = None
                    max_a = None
                    for q, a in factor(b).items():
                        val = q ** a
                        if val > max_val:
                            max_val = val
                            max_p = q
                            max_a = a
                    H_check = h_p_e(max_p, s * max_a)
                    if f_b == H_check:
                        sols.add(b)
        p_candidates = set()
        for p in range(2, 4 * s + 5):
            if is_prime(p):
                p_candidates.add(p)
        for p in [2, 3, 5, 7, 11, 13, 17, 19]:
            if is_prime(p):
                p_candidates.add(p)
        for p in sorted(p_candidates):
            add_solutions_for(p)
        return sorted(sols)
    sols = enumerate_solutions(s)
    # Enforce non-triviality: at least 2 solutions
    if len(sols) < 2:
        return (False, None)
    # Format the answer as required
    ans_str = '### The final answer is: $\\boxed{\\{' + ', '.join(str(x) for x in sols) + '\\}}$'
    return (True, ans_str)
